window.PythonReferenceEnglish = (() => {
    function entry(title, question, explanation, tryThis, aliases, code, expected) {
        const topic = {title, question, explanation, tryThis, aliases};
        if (code !== undefined) Object.assign(topic, {code, expected});
        return topic;
    }
    // Examples that use only numbers or Python keywords share the original executable example.
    return {
        range: entry('range() · A sequence of numbers', 'Why doesn’t range(1, 5) print 5?',
            'The first number is included. The stop value is excluded, so this loop visits 1, 2, 3 and 4.',
            'Change the stop value to 6 so that the loop also prints 5.',
            ['last number missing', 'stop value', 'range end', 'why is the last number missing']),
        print: entry('print() · Show a result', 'How can I print text and a number together?',
            'Give print() several values separated by commas. It puts a space between them and starts a new line after the last value.',
            'Change the coin count and add a third line with your own message.',
            ['display text', 'print a message', 'output', 'hello world', 'new line'],
            'print("Coins found", 3)\nprint("Next stop")', 'Coins found 3\nNext stop'),
        variable: entry('Variables · Keep a value', 'How do I change a score that I already stored?',
            'Python evaluates the right side of an assignment first. Here it adds 3 to the old score, then stores the result under the same name.',
            'Replace score = score + 3 with score += 5 and predict the result.',
            ['assignment', 'update a variable', 'increase score', '+=']),
        for: entry('for · Visit every item', 'How can I use each item in my backpack?',
            'A for loop assigns one item at a time to item. The indented line runs once for each item in the list.',
            'Add a fourth item to the list and run the loop again.',
            ['for loop', 'iterate a list', 'loop through items', 'repeat for each'],
            'bag = ["rope", "lantern", "compass"]\nfor item in bag:\n    print(item)', 'rope\nlantern\ncompass'),
        if: entry('if, elif, else · Choose a path', 'How do I pick a medal based on a score?',
            'Python checks the branches from top to bottom. It runs the first branch whose condition is true. If none match, it runs else.',
            'Try scores of 4, 5 and 8. Which medal does each score earn?',
            ['conditional', 'if else', 'choose a branch', 'multiple conditions'],
            'score = 6\nif score >= 8:\n    print("Gold")\nelif score >= 5:\n    print("Silver")\nelse:\n    print("Bronze")', 'Silver'),
        compare: entry('Comparisons · Include the boundary', 'How do I include a value exactly on the limit?',
            'A strict comparison such as < excludes the boundary. The operators <= and >= include equality, so 30 <= 30 is true.',
            'Change charge to 29, and then to 31. Compare both results.',
            ['greater than or equal', 'less than or equal', 'at least', 'at most', 'boundary', '>=', '<=']),
        equal: entry('== and != · Compare values', 'How do I check if two values are equal?',
            'Use == to compare two values and != to check whether they differ. A single = stores a value in a variable.',
            'Change keys to 3 and predict both lines of output.',
            ['equals', 'not equal', 'equality', '==', '!=']),
        logic: entry('and, or, not · Combine conditions', 'How can I check two conditions together?',
            'and requires both conditions to be true. or needs at least one true condition. not reverses a truth value.',
            'Set at_gate to True. Predict which of the three answers will change.',
            ['boolean', 'boolean operators', 'both conditions', 'either condition']),
        while: entry('while · Repeat until a condition changes', 'Why does my loop never stop?',
            'A while loop checks its condition before each pass. Subtracting one from steps moves it toward zero, where steps > 0 becomes false.',
            'Start with steps = 5 and see how many times the loop runs.',
            ['infinite loop', 'never ends', 'never stops', 'countdown', 'endless loop']),
        modulo: entry('% · Find the remainder', 'How do I tell whether a number is even?',
            'The % operator returns the remainder after division. An integer is even when its remainder after division by 2 is zero.',
            'Try 8 instead of 7. What happens to the remainder and the Boolean result?',
            ['remainder', 'odd', 'even', 'modulus', '%']),
        index: entry('Indexes · Get one item', 'Why do I get IndexError when reading a list?',
            'The first item has index 0. In a list of three items, index 2 is the last item. Index -1 reads the last item as well.',
            'Try bag[0], then bag[3]. Which one is outside the list?',
            ['IndexError', 'list index out of range', 'first item', 'last item', 'negative index'],
            'bag = ["stone", "rope", "cup"]\nprint(bag[2])\nprint(bag[-1])', 'cup\ncup'),
        append: entry('append() · Add to a list', 'How do I add an item to the end of a list?',
            'list.append(item) changes the original list. Print the list after the call to see the item you added.',
            'Add a second append() call with an item of your choice.',
            ['append', 'add to list', 'add an item', 'insert at end'],
            'bag = ["rope"]\nbag.append("map")\nprint(bag)', "['rope', 'map']"),
        len: entry('len() · Count items', 'How do I find the length of a list or string?',
            'len() counts items in a list. With a string it returns the number of characters, including spaces.',
            'Add one item to bag, then try len("two words").',
            ['list length', 'number of items', 'count characters', 'string length'],
            'bag = ["rope", "water", "key"]\nprint(len(bag))\nprint(len("sun"))', '3\n3'),
        sum: entry('sum() · Add a collection of numbers', 'How do I add all the numbers in a list?',
            'sum() adds every number in the collection and returns the total. A zero contributes nothing to the sum.',
            'Add a negative number to coins and predict the new total.',
            ['add all numbers', 'list total', 'sum of a list']),
        dictionary: entry('dict · Look up a key', 'How can I read a key that might be missing?',
            'Square brackets read the value for a key. If the key is missing, Python raises KeyError. get(key, default) returns your chosen default instead.',
            'Add "key": 3 to stock, and run the example again.',
            ['KeyError', 'missing key', 'dictionary', 'default value', 'get'],
            'stock = {"water": 2, "rope": 1}\nprint(stock["water"])\nprint(stock.get("key", 0))', '2\n0'),
        function: entry('def and return · Reuse a calculation', 'How do I use the result of a function?',
            'def defines a function. return sends a value back to the caller. Here double(4) returns 8, which is stored in reward and printed.',
            'Call double() with 6, then add 1 to the returned value.',
            ['define a function', 'return value', 'parameter', 'return vs print']),
        types: entry('int() and str() · Convert a value', 'Why can’t I add a number to text?',
            'The string "12" is text. int() converts it to an integer for arithmetic. str() converts a number to text so it can be joined with another string.',
            'Change amount to "20" and predict the first line.',
            ['TypeError', 'convert to int', 'integer to string', 'string to number', 'concatenate'],
            'amount = "12"\nprint(int(amount) + 3)\nprint("Coins: " + str(15))', '15\nCoins: 15'),
        indent: entry('Indentation · Group lines', 'Why am I getting an IndentationError?',
            'Indent the lines that belong to an if, loop or function. This example uses four spaces inside if. The last print starts at the left edge, so it runs every time.',
            'Set coins to 1, run the code, and compare the two lines.',
            ['IndentationError', 'unexpected indent', 'expected an indented block', 'TabError'],
            'coins = 0\nif coins > 0:\n    print("You have coins")\nprint("Check complete")', 'Check complete'),
        syntax: entry('SyntaxError · Check the code’s spelling', 'What should I check after a SyntaxError?',
            'Check the marked line and the one before it for a missing quote, bracket or colon. An if statement needs a colon before its indented block.',
            'Remove the colon after 2 < 3 to read the error, then put it back.',
            ['SyntaxError', 'invalid syntax', 'missing colon', 'unclosed bracket'],
            'if 2 < 3:\n    print("The gate is open")', 'The gate is open'),
        name: entry('NameError · Find an unknown name', 'Why does Python say a name is not defined?',
            'Assign a value before reading a variable. Its spelling and capitalization must match each time you use it.',
            'Change print(points) to print(Points). Then fix the name.',
            ['NameError', 'not defined', 'undefined variable', 'name is not defined']),
        division: entry('/ and // · Divide numbers', 'How can I divide coins into whole shares?',
            '/ performs ordinary division. // rounds the quotient down, so 11 // 2 gives 5 whole coins per person.',
            'Set coins to 12 and compare the results of / and //.',
            ['floor division', 'integer division', 'whole shares', '//', '/']),
        fstring: entry('f-strings · Place values in text', 'How do I put a variable inside a message?',
            'Put f before the opening quote. Python replaces the expressions inside braces with their values.',
            'Change the hero’s name and score and run the same print statement again.',
            ['fstring', 'f string', 'format string', 'interpolation', 'variables in text'],
            'hero = "Ari"\nscore = 4\nprint(f"{hero} found {score} coins.")', 'Ari found 4 coins.'),
        break: entry('break · Leave a loop early', 'How do I stop a loop when I reach a wall?',
            'break immediately exits the nearest loop. Here it runs before print, so the wall and everything after it are skipped.',
            'Put the wall first, then last, and compare what gets printed.',
            ['stop a loop early', 'exit loop', 'break statement'],
            'for place in ["river", "wall", "field"]:\n    if place == "wall":\n        break\n    print(place)', 'river'),
        contains: entry('in · Check membership', 'How do I check whether something is in a list?',
            'The expression item in collection returns True or False. For strings, in tests whether one string occurs inside another.',
            'Add "key" to the backpack and run both checks again.',
            ['in', 'membership', 'is in a list', 'item is in a list', 'list contains', 'item exists', 'find in list'],
            'bag = ["rope", "water"]\nprint("key" in bag)\nprint("water" in bag)', 'False\nTrue'),
        slice: entry('Slices · Take part of a sequence', 'How do I take part of a string?',
            'A slice starts at the first index and stops before the second. Leaving out a boundary uses the start or end of the sequence.',
            'Replace 3 with 2 in both slices and predict the new split.',
            ['slice', 'substring', 'first three characters', 'part of a list'],
            'word = "lantern"\nprint(word[:3])\nprint(word[3:])', 'lan\ntern'),
        sort: entry('sorted() · Put items in order', 'How do I sort a list from largest to smallest?',
            'sorted() returns a new list in ascending order. Set reverse=True for descending order. The original list keeps its order.',
            'Add print(points) to check the original after sorting.',
            ['sort descending', 'sort ascending', 'largest to smallest', 'reverse order']),
        value: entry('ValueError · Check input before converting', 'Why does int() reject my input?',
            'int() needs text that represents an integer. This example only accepts unsigned ASCII digits before converting, and handles other input in the else branch.',
            'Change text to "4a" or an empty string and run it again.',
            ['ValueError', 'invalid literal for int', 'isdigit', 'validate input', 'empty string'],
            'text = "42"\nif text.isascii() and text.isdigit():\n    print(int(text) + 1)\nelse:\n    print("Enter digits")', '43')
    };
})();
